
const WORDS=[{"id": 0, "w": "背叛", "p": "bèipàn", "t": "动词", "m": "phản bội", "coll": "背叛朋友、背叛信任", "s": "真正的朋友不会为了眼前的利益背叛彼此的信任。"}, {"id": 1, "w": "上进", "p": "shàngjìn", "t": "动词", "m": "cầu tiến, phấn đấu tiến bộ", "coll": "积极上进、要求上进", "s": "她一直积极上进，下班后仍坚持学习新的技能。"}, {"id": 2, "w": "抱负", "p": "bàofù", "t": "名词", "m": "hoài bão, tham vọng, khát vọng", "coll": "远大抱负、实现抱负", "s": "他从小就怀有远大抱负，希望将来成为一名优秀的科学家。"}, {"id": 3, "w": "魄力", "p": "pòlì", "t": "名词", "m": "tính quyết đoán, sự gan dạ và cương quyết", "coll": "有魄力、改革的魄力", "s": "面对复杂的局面，这位负责人表现出了果断改革的魄力。"}, {"id": 4, "w": "开阔", "p": "kāikuò", "t": "形容词", "m": "cởi mở, khoáng đạt", "coll": "开阔眼界、视野开阔", "s": "阅读不同领域的书籍有助于开阔眼界。"}, {"id": 5, "w": "处境", "p": "chǔjìng", "t": "名词", "m": "cảnh ngộ, hoàn cảnh", "coll": "艰难的处境、改善处境", "s": "即使处境艰难，她也没有放弃自己的目标。"}, {"id": 6, "w": "打击", "p": "dǎjī", "t": "动词", "m": "đả kích, công kích, đánh", "coll": "遭受打击、沉重的打击", "s": "这次失败给了他沉重的打击，但他很快重新振作起来。"}, {"id": 7, "w": "脆弱", "p": "cuìruò", "t": "形容词", "m": "yếu đuối, yếu ớt", "coll": "内心脆弱、脆弱的关系", "s": "外表坚强的人也可能有内心脆弱的时候。"}, {"id": 8, "w": "榜样", "p": "bǎngyàng", "t": "名词", "m": "tấm gương, gương tốt", "coll": "树立榜样、学习榜样", "s": "老师以身作则，为学生树立了良好的榜样。"}, {"id": 9, "w": "光彩", "p": "guāngcǎi", "t": "名词／形容词", "m": "ánh hào quang, vẻ rực rỡ; vẻ vang", "coll": "焕发光彩、增添光彩", "s": "经过修复，这座古老的建筑重新焕发了光彩。"}, {"id": 10, "w": "理智", "p": "lǐzhì", "t": "名词／形容词", "m": "lý trí; có lý trí, tỉnh táo", "coll": "保持理智、理智的选择", "s": "面对争论，我们应保持理智，先听清楚对方的意见。"}, {"id": 11, "w": "哭泣", "p": "kūqì", "t": "动词", "m": "khóc sụt sùi, khóc thút thít", "coll": "低声哭泣、停止哭泣", "s": "看到孩子独自坐在角落里哭泣，老师轻轻地走了过去。"}, {"id": 12, "w": "否决", "p": "fǒujué", "t": "动词", "m": "phủ quyết, bác bỏ", "coll": "否决提案、一票否决", "s": "经过充分讨论，委员会否决了这项提案。"}, {"id": 13, "w": "出息", "p": "chūxi", "t": "名词", "m": "tiền đồ, triển vọng; sự thành đạt", "coll": "有出息、没出息", "s": "父母希望孩子将来有出息，也关心他们是否过得快乐。"}, {"id": 14, "w": "娃娃", "p": "wáwa", "t": "名词", "m": "em bé", "coll": "可爱的娃娃、布娃娃", "s": "小女孩抱着心爱的布娃娃，安静地坐在沙发上。"}, {"id": 15, "w": "潜移默化", "p": "qiányí mòhuà", "t": "成语", "m": "ảnh hưởng, thay đổi âm thầm và dần dần mà không hay biết", "coll": "潜移默化的影响、潜移默化地改变", "s": "家庭氛围会在潜移默化中影响孩子的行为习惯。"}, {"id": 16, "w": "鞭策", "p": "biāncè", "t": "动词", "m": "thúc giục, giục giã", "coll": "鞭策自己、不断鞭策", "s": "老师的鼓励一直鞭策着我，让我不敢轻易放弃。"}, {"id": 17, "w": "赋予", "p": "fùyǔ", "t": "动词", "m": "trao cho, giao phó", "coll": "赋予意义、赋予权利", "s": "不同的经历赋予了这件礼物特殊的意义。"}, {"id": 18, "w": "扮演", "p": "bànyǎn", "t": "动词", "m": "sắm vai, đóng vai", "coll": "扮演角色、扮演主角", "s": "她在这部话剧中扮演一位勇敢而善良的医生。"}, {"id": 19, "w": "鄙视", "p": "bǐshì", "t": "动词", "m": "xem thường, khinh thường", "coll": "鄙视他人、受到鄙视", "s": "我们不应该因为别人的职业而鄙视他们。"}, {"id": 20, "w": "讥笑", "p": "jīxiào", "t": "动词", "m": "chế nhạo, nhạo báng", "coll": "讥笑别人、遭到讥笑", "s": "面对同学的失误，他没有讥笑，而是主动帮助对方改正。"}, {"id": 21, "w": "恶心", "p": "ěxin", "t": "动词／形容词", "m": "buồn nôn; ghê tởm, gây khó chịu", "coll": "感到恶心、令人恶心", "s": "车里浓重的汽油味让她感到恶心。"}, {"id": 22, "w": "体面", "p": "tǐmiàn", "t": "形容词", "m": "vẻ vang, vinh dự, chỉnh tề", "coll": "穿着体面、体面的工作", "s": "参加正式活动时，穿着整洁体面是对他人的尊重。"}, {"id": 23, "w": "含糊", "p": "hánhu", "t": "形容词", "m": "mơ hồ, không rõ ràng; mập mờ", "coll": "含糊其辞、回答含糊", "s": "这个问题关系到大家的利益，请不要含糊其辞。"}, {"id": 24, "w": "束缚", "p": "shùfù", "t": "动词", "m": "ràng buộc, trói buộc", "coll": "摆脱束缚、思想束缚", "s": "他希望摆脱旧观念的束缚，尝试一种全新的创作方式。"}, {"id": 25, "w": "魔鬼", "p": "móguǐ", "t": "名词", "m": "ma quỷ", "coll": "可怕的魔鬼、魔鬼的形象", "s": "故事里的魔鬼虽然看起来可怕，却也有温柔的一面。"}, {"id": 26, "w": "神仙", "p": "shénxiān", "t": "名词", "m": "thần tiên", "coll": "神仙故事、神仙般的生活", "s": "传说中的神仙能够腾云驾雾，往来于天地之间。"}, {"id": 27, "w": "健全", "p": "jiànquán", "t": "形容词", "m": "khỏe mạnh, hoàn thiện, hoàn hảo", "coll": "制度健全、健全机制", "s": "这家机构建立了健全的管理制度，各项工作都有明确的流程。"}, {"id": 28, "w": "塌", "p": "tā", "t": "动词", "m": "đổ, sụp", "coll": "房屋倒塌、塌下来", "s": "这座年久失修的房子在暴雨中塌了。"}, {"id": 29, "w": "反之", "p": "fǎnzhī", "t": "连词", "m": "trái lại, ngược lại", "coll": "反之亦然、反之则不然", "s": "充分准备通常能提高效率；反之，仓促行动容易出错。"}, {"id": 30, "w": "激素", "p": "jīsù", "t": "名词", "m": "hormone", "coll": "激素水平、激素研究", "s": "这篇论文讨论了激素研究中的几种常用方法。"}, {"id": 31, "w": "转移", "p": "zhuǎnyí", "t": "动词", "m": "chuyển, thay đổi", "coll": "转移注意力、转移物资", "s": "救援人员连夜转移物资，确保安置点有足够的生活用品。"}, {"id": 32, "w": "喉咙", "p": "hóulóng", "t": "名词", "m": "cổ họng", "coll": "喉咙不舒服、清清喉咙", "s": "正式发言之前，他轻轻地清了清喉咙。"}, {"id": 33, "w": "鼻涕", "p": "bítì", "t": "名词", "m": "nước mũi", "coll": "流鼻涕、擦鼻涕", "s": "孩子流着鼻涕，妈妈递给他一张纸巾。"}, {"id": 34, "w": "之际", "p": "zhī jì", "t": "固定结构", "m": "vào lúc, nhân dịp", "coll": "离别之际、新年之际", "s": "新年到来之际，学校向全体师生送上了祝福。"}, {"id": 35, "w": "修复", "p": "xiūfù", "t": "动词", "m": "sửa chữa, phục hồi lại", "coll": "修复文物、修复关系", "s": "专家们花了几个月时间，终于修复了这幅破损的古画。"}, {"id": 36, "w": "宣泄", "p": "xuānxiè", "t": "动词", "m": "giải tỏa, trút ra (cảm xúc)", "coll": "宣泄情绪、宣泄不满", "s": "她把心里的烦恼写进日记，借此宣泄积压的情绪。"}, {"id": 37, "w": "许可", "p": "xǔkě", "t": "动词", "m": "cho phép", "coll": "获得许可、未经许可", "s": "未经许可，请不要进入这间实验室。"}, {"id": 38, "w": "倡导", "p": "chàngdǎo", "t": "动词", "m": "khởi xướng, chủ trương", "coll": "倡导节约、倡导新风尚", "s": "学校倡导从身边的小事做起，共同营造节约的风气。"}, {"id": 39, "w": "情理", "p": "qínglǐ", "t": "名词", "m": "tình lý, lẽ thường, lẽ phải", "coll": "合乎情理、情理之中", "s": "他提出的要求合乎情理，大家都表示支持。"}, {"id": 40, "w": "忌讳", "p": "jìhuì", "t": "动词", "m": "kiêng kị, kiêng cử", "coll": "有所忌讳、忌讳的话题", "s": "与不同文化背景的人交往时，应了解对方忌讳的话题。"}, {"id": 41, "w": "外界", "p": "wàijiè", "t": "名词", "m": "thế giới bên ngoài", "coll": "外界影响、与外界联系", "s": "为了专心完成研究，他暂时减少了与外界的联系。"}, {"id": 42, "w": "狭隘", "p": "xiá'ài", "t": "形容词", "m": "hẹp hòi, hạn hẹp", "coll": "心胸狭隘、狭隘的观念", "s": "如果总用狭隘的眼光看问题，就很难理解不同的观点。"}, {"id": 43, "w": "偏见", "p": "piānjiàn", "t": "名词", "m": "thành kiến", "coll": "消除偏见、带有偏见", "s": "只有增加了解，才能逐渐消除彼此的偏见。"}, {"id": 44, "w": "阻挠", "p": "zǔnáo", "t": "动词", "m": "cản trở, ngăn cản", "coll": "百般阻挠、受到阻挠", "s": "尽管受到多方面的阻挠，调查工作仍然继续进行。"}, {"id": 45, "w": "尊严", "p": "zūnyán", "t": "名词", "m": "tôn nghiêm, phẩm giá, lòng tự trọng", "coll": "维护尊严、人格尊严", "s": "无论一个人从事什么工作，他的尊严都应受到尊重。"}, {"id": 46, "w": "理睬", "p": "lǐcǎi", "t": "动词", "m": "để ý, đoái hoài, quan tâm", "coll": "不予理睬、没人理睬", "s": "他专心看书，没有理睬周围的议论。"}, {"id": 47, "w": "淹没", "p": "yānmò", "t": "动词", "m": "chìm ngập", "coll": "被洪水淹没、淹没村庄", "s": "连续的暴雨使河水上涨，淹没了岸边的农田。"}, {"id": 48, "w": "须知", "p": "xūzhī", "t": "动词", "m": "nhất định phải biết", "coll": "须知事项、须知来之不易", "s": "我们应珍惜粮食，须知每一粒米都来之不易。"}, {"id": 49, "w": "抹杀", "p": "mǒshā", "t": "动词", "m": "gạt bỏ, xóa bỏ", "coll": "抹杀贡献、不可抹杀", "s": "不能因为他的一次失误，就抹杀他过去的贡献。"}, {"id": 50, "w": "岁月", "p": "suìyuè", "t": "名词", "m": "năm tháng", "coll": "漫长岁月、岁月流逝", "s": "无论岁月怎样流逝，她始终记得老师的教诲。"}, {"id": 51, "w": "沉淀", "p": "chéndiàn", "t": "动词", "m": "lắng đọng, kết tủa", "coll": "沉淀经验、沉淀下来", "s": "经过多年的实践，这些经验逐渐沉淀下来，成为团队的宝贵财富。"}];
