'use strict';
const root=document.getElementById('ntc-design-preview');
const $=id=>document.getElementById(id);
const STORE='ngocthucac-hsk6-bai32-learning-v3';
const pages=['词汇表','学习生词','词汇卡片','综合练习','连词成句','学习统计'];
let storageOK=true,store={active:null,profiles:{}};
try{let raw=localStorage.getItem(STORE);if(raw){let parsed=JSON.parse(raw);if(parsed&&parsed.profiles)store=parsed}}catch(e){storageOK=false}
let student=store.active?store.profiles[store.active]:null;
if(!student){store.active='local';student=store.profiles.local||createStudent('','');store.profiles.local=student;}
let ui=student?.ui||{page:0,g:0,idx:0,pinyin:false};
let speed=1,playback=null,audioGeneration=0;
const group=g=>WORDS.slice(g*10,g===4?WORDS.length:g*10+10);
const groupOf=id=>Math.min(4,Math.floor(id/10));
const escapeHTML=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const hasLearned=id=>!!student?.studied.includes(id);
const learned=g=>group(g).filter(d=>hasLearned(d.id)).length;
const allLearned=()=>!!student&&student.studied.length===WORDS.length;
const memory=id=>student?.memory[id]||'new';
const weakIds=()=>WORDS.filter(d=>memory(d.id)==='review').map(d=>d.id);
const totalLearned=()=>student?.studied.length||0;
const currentWord=()=>group(ui.g)[ui.idx];
function gate(){return `<div class="ntc-panel ntc-lock"><div class="ntc-kicker">先学习生词，再进行全课复习</div><h2>请先完成生词学习</h2><p>已学习 ${totalLearned()}/52 个词语。学完5组词语后，即可进行词汇卡片、综合练习和连词成句。</p>${meter(totalLearned(),52)}<div class="ntc-progressgroups">${[0, 1, 2, 3, 4].map(g=>`<button data-group="${g}">组别 ${g+1}<br>${learned(g)}/${group(g).length}个词语</button>`).join('')}</div>${button('继续学习 →','resume','ntc-primary')}</div>`}
function listView(){return `<div class="ntc-panel">${heading('词汇表','全课共52个词语，点击 ↗ 学习该词语',totalLearned()+'/52 已学习')}<div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>汉字</th><th class="ntc-colpinyin">拼音</th><th class="ntc-coltype">词性</th><th>越南语释义</th><th>状态</th></tr></thead><tbody>${WORDS.map((d,i)=>`<tr><td class="ntc-hanzi">${d.w} <button class="ntc-play" data-word="${i}" aria-label="学习词语 ${d.w}">↗</button><button class="ntc-play" data-audio-word="${i}" aria-label="听词语 ${d.w}">◖</button></td><td class="ntc-colpinyin">${escapeHTML(d.p)}</td><td class="ntc-coltype">${escapeHTML(d.t)}</td><td>${escapeHTML(d.m)}</td><td>${status(i)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-actions"><span class="ntc-caption">仅生词学习分为五组：10、10、10、10、12个词语。</span>${button('开始／继续学习 →','resume','ntc-primary')}</div></div>`}
function studyView(){let d=currentWord(),a=group(ui.g),isLast=d.id===51;return `<div class="ntc-panel">${heading('学习生词 · 组别 '+(ui.g+1),'学习词语、搭配与例句',`${ui.idx+1}/${a.length}`)}${meter(learned(ui.g),a.length)}<div class="ntc-study"><div class="ntc-wordbox"><div class="ntc-pinyin" style="visibility:${ui.pinyin?'visible':'hidden'}">${escapeHTML(d.p)}</div><div class="ntc-bigword ntc-writing" id="ntc-writing" aria-label="汉字笔顺">${d.w}</div><div class="ntc-meaning">${escapeHTML(d.m)}</div><span class="ntc-type">${escapeHTML(d.t)}</span><div class="ntc-smallbtns">${button('笔顺演示','strokes')}<button data-audio-word="${d.id}">◖ 听词语</button>${button(ui.pinyin?'隐藏拼音':'显示拼音','pinyin')}</div></div><div><div class="ntc-label">常用搭配</div><div class="ntc-cn">${escapeHTML(d.coll)}</div><hr><div class="ntc-label">例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><div class="ntc-smallbtns"><button data-audio-example="${d.id}">◖ 听例句</button></div><div class="ntc-note">${status(d.id)}</div></div></div><div class="ntc-actions">${button('← 上一个','prev-study','',d.id===0)}${button(isLast?'✓ 已学习 · 全课复习 →':ui.idx===a.length-1?'✓ 已学习 · 下一组 →':'✓ 已学习 · 下一个 →','mark-study','ntc-primary')}</div><div class="ntc-footnote">点击“已学习”记录学习进度。需要时，可点击“笔顺演示”查看汉字的书写顺序。</div></div>`}
function markStudy(){let d=currentWord();if(!student.studied.includes(d.id))student.studied.push(d.id);let next=WORDS.find(x=>!student.studied.includes(x.id));if(d.id<51){let id=d.id+1;ui.g=groupOf(id);ui.idx=id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx}}else if(!next){ui.page=2;student.bookmark={g:4,idx:11};if(!student.flash)startFlash('all',false)}else{ui.g=groupOf(next.id);ui.idx=next.id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx};toast('还有未学完的词语，请继续学习。')}save();render()}
function flashView(){let f=student.flash;if(f.done)f.done=false;let d=WORDS[f.ids[f.at]];return `<div class="ntc-panel">${heading('词汇卡片 · 全课复习',f.filter==='weak'?'复习练习中答错的词语':'全课52个词语随机排列，不分组',`${f.at+1}/${f.ids.length}`)}${meter(f.at+1,f.ids.length)}<div class="ntc-smallbtns" style="margin-bottom:16px">${button('重新打乱全课52个词语','flash-all')}${button('待复习词语 ('+weakIds().length+')','flash-weak','',!weakIds().length)}</div><div class="ntc-flash"><span class="ntc-label">${f.flipped?'背面':'正面'}</span>${f.flipped?`<span class="ntc-pinyin">${escapeHTML(d.p)}</span><span class="ntc-meaning">${escapeHTML(d.m)}</span><span class="ntc-type">${escapeHTML(d.t)}</span><small>${escapeHTML(d.coll)}</small><div class="ntc-note"><span class="ntc-cn">${escapeHTML(d.s)}</span><button class="ntc-play" data-audio-example="${d.id}" aria-label="听例句">◖</button></div>`:`<div style="display:flex;align-items:center;justify-content:center;gap:12px"><span class="ntc-bigword" style="font-size:clamp(51px,${d.w.length>2?'7':'10'}vw,${d.w.length>2?'80':'112'}px)">${d.w}</span><button class="ntc-play" data-audio-word="${d.id}" aria-label="听发音 ${d.w}" title="听发音">🔊</button></div>`}<div class="ntc-smallbtns">${button(f.flipped?'↶ 返回正面':'查看释义与例句 ↻','flip')}</div></div><div class="ntc-actions">${button('← 上一张','flash-prev','',f.at===0)}${f.at===f.ids.length-1?button('综合练习 →','quiz-page','ntc-primary'):button('下一张 →','flash-next','ntc-primary')}</div><div class="ntc-footnote">先看正面回忆词义；需要时翻到背面查看拼音、释义与例句。无需翻面即可切换卡片。</div></div>`}
const contextAlternatives={"2": [0, 11, 12], "5": [0, 11, 12], "8": [0, 11, 12], "11": [2, 25, 30], "14": [0, 11, 12], "17": [2, 25, 30], "20": [2, 25, 30], "23": [2, 25, 30], "26": [0, 11, 12], "29": [2, 25, 30], "32": [0, 11, 12], "35": [2, 25, 30], "38": [2, 25, 30], "41": [0, 11, 12], "44": [2, 25, 30], "47": [2, 25, 30], "50": [0, 11, 12]};
function orderView(){let o=student.order;if(o.done)return orderResults();let id=o.ids[o.at],d=WORDS[id],chunks=CHUNKS[id],ok=o.selected.every((x,i)=>x===i);return `<div class="ntc-panel">${heading('连词成句 · 全课复习','使用已学的52个例句，题目随机排列',`${o.at+1}/${o.ids.length}题`)}${meter(o.at,o.ids.length)}<div class="ntc-label">重点词语 · ${d.w}</div><p class="ntc-caption">按顺序选择词语，点击已选词语可将其放回。</p><div class="ntc-orderanswer ${o.checked?(ok?'ntc-correct':'ntc-wrong'):''}" aria-label="已排列的句子">${o.selected.length?o.selected.map((index,i)=>`<button data-remove="${i}" ${o.checked?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join(''):'<span class="ntc-caption">请在这里排列句子……</span>'}</div><div class="ntc-chunks" aria-label="待选词语">${o.bank.map(index=>`<button class="${o.selected.includes(index)?'used':''}" data-chunk="${index}" ${o.checked||o.selected.includes(index)?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join('')}</div><div class="ntc-actions"><div class="ntc-smallbtns">${button('↶ 撤销最后一项','order-undo','',!o.selected.length||o.checked)}${button('重新排列','order-clear','',!o.selected.length||o.checked)}</div>${button('检查答案','order-check','ntc-primary',o.selected.length!==chunks.length||o.checked)}</div>${o.checked?`<div class="ntc-note" role="status"><strong>${ok?'✓ 与例句顺序一致':'✕ 与例句顺序不一致'}</strong><div class="ntc-label">原例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><button data-audio-example="${id}">◖ 听例句</button></div><div class="ntc-actions"><span></span>${button(o.at===o.ids.length-1?'查看结果 →':'下一题 →','order-next','ntc-primary')}</div>`:''}<div class="ntc-footnote">本练习按原例句顺序评分，其他语序也可能符合语法。</div></div>`}
function orderResults(){let o=student.order,wrong=o.answers.filter(x=>!x.ok).map(x=>x.id),correct=o.answers.length-wrong.length;return `<div class="ntc-panel">${heading('连词成句结果','第32课综合复习')}<div class="ntc-score">${correct}<small> / ${o.answers.length}题答对</small></div><div class="ntc-tag">${wrong.length} 题需要重新练习</div>${wrong.map(id=>`<div class="ntc-miniresult"><strong>${WORDS[id].w}</strong><br><span class="ntc-cn">${escapeHTML(WORDS[id].s)}</span></div>`).join('')}<div class="ntc-actions">${button('重新练习全课句子','order-restart')}${button('重练错题','order-retry','',!wrong.length)}${button('查看学习统计 →','stats-page','ntc-primary')}</div></div>`}
function statsView(){let weak=weakIds();return `<div class="ntc-panel">${heading('学习统计','当前浏览器中的第32课学习进度','第32课 · 52个词语')}<div class="ntc-statrow"><div class="ntc-stat"><label>已学词语</label><strong>${totalLearned()}<small> / 52</small></strong></div><div class="ntc-stat"><label>需要复习</label><strong>${weak.length}<small>个词语</small></strong></div></div><div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>组别</th><th>已学习</th><th>待复习</th><th>综合练习</th><th>连词成句</th></tr></thead><tbody>${[0, 1, 2, 3, 4].map(g=>`<tr><td>组别 ${g+1}<div class="ntc-caption">${group(g).length}个词语</div></td><td>${learned(g)}/${group(g).length}</td><td>${group(g).filter(d=>memory(d.id)==='review').length}</td><td>${activityScore('quiz',g)}</td><td>${activityScore('order',g)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-footnote">按词语所属组显示答对题数／已答题数。优先显示本轮进度，否则显示最近一轮结果。</div><hr><div class="ntc-sectionhead"><h2>待复习词语</h2>${button('用词汇卡片复习 →','flash-weak','',!weak.length||!allLearned())}</div><div class="ntc-terms">${weak.length?weak.map(id=>`<button data-word="${id}">${WORDS[id].w}</button>`).join(''):'<span class="ntc-caption">暂无需要复习的错词。</span>'}</div><div class="ntc-note">继续学习：组别 ${student.bookmark.g+1} · 词语 ${student.bookmark.idx+1}/${group(student.bookmark.g).length}.<br>本页累计学习时间约 ${Math.floor(student.timeMs/60000)} 分钟。已完成综合练习轮数： ${student.quizHistory.length}; 连词成句轮数： ${student.orderHistory.length}.</div><div class="ntc-actions">${button('继续学习','resume','ntc-primary')}${button('导出学习记录','backup')}${button('恢复学习记录','restore')}</div><div class="ntc-footnote">答错词语会列入待复习词语。浏览词汇卡片不等于掌握词语。</div></div>`}
function render(){clearWriting();let total=totalLearned();$('ntc-profile-button').textContent='HSK6 · 第32课';$('ntc-bookmark').textContent=student?total+'/52 个已学词语':'';$('ntc-tabs').innerHTML=pages.map((name,i)=>`<button class="ntc-tab ${ui.page===i?'active':''}" data-page="${i}" aria-pressed="${ui.page===i}">${i<5?i+1+'. ':''}${name}${i>=2&&i<=4&&!allLearned()?' 🔒':''}</button>`).join('');let showGroups=ui.page===1;$('ntc-groups').hidden=!showGroups;$('ntc-groups').innerHTML=showGroups?[0, 1, 2, 3, 4].map(g=>`<button data-group="${g}" class="${g===ui.g?'active':''}">组别 ${g+1} · ${group(g).length}个词语 · ${learned(g)}/${group(g).length}</button>`).join(''):'';$('ntc-sidegroups').innerHTML=showGroups?'<div class="ntc-navtitle">当前词汇组</div>'+[0, 1, 2, 3, 4].map(g=>`<button class="ntc-sidegroup ${g===ui.g?'active':''}" data-group="${g}"><span>组别 ${g+1}<br><small>词语 ${g*10+1}–${g*10+group(g).length}</small></span><small>${learned(g)}/${group(g).length}</small></button>`).join(''):'<div class="ntc-navtitle">第32课学习进度</div><div style="padding:0 10px">'+total+'/52 个已学词语'+meter(total,52)+'</div>';$('ntc-sidefoot').innerHTML='学完生词 →<br>全课综合复习。<br><br>进度保存在<br>当前浏览器中。';let html;if(ui.page>=2&&ui.page<=4&&!allLearned())html=gate();else html=[listView,studyView,flashView,quizView,orderView,statsView][ui.page]();$('ntc-view').innerHTML=html;if(ui.page===1)setupWriting();}
const AUDIO_INDEX={"背叛":"data:audio/mpeg;base64,","真正的朋友不会为了眼前的利益背叛彼此的信任。":"data:audio/mpeg;base64,","上进":"data:audio/mpeg;base64,","她一直积极上进，下班后仍坚持学习新的技能。":"data:audio/mpeg;base64,","抱负":"data:audio/mpeg;base64,","他从小就怀有远大抱负，希望将来成为一名优秀的科学家。":"data:audio/mpeg;base64,","魄力":"data:audio/mpeg;base64,","面对复杂的局面，这位负责人表现出了果断改革的魄力。":"data:audio/mpeg;base64,","开阔":"data:audio/mpeg;base64,","阅读不同领域的书籍有助于开阔眼界。":"data:audio/mpeg;base64,","处境":"data:audio/mpeg;base64,","即使处境艰难，她也没有放弃自己的目标。":"data:audio/mpeg;base64,","打击":"data:audio/mpeg;base64,","这次失败给了他沉重的打击，但他很快重新振作起来。":"data:audio/mpeg;base64,","脆弱":"data:audio/mpeg;base64,","外表坚强的人也可能有内心脆弱的时候。":"data:audio/mpeg;base64,","榜样":"data:audio/mpeg;base64,","老师以身作则，为学生树立了良好的榜样。":"data:audio/mpeg;base64,","光彩":"data:audio/mpeg;base64,","经过修复，这座古老的建筑重新焕发了光彩。":"data:audio/mpeg;base64,","理智":"data:audio/mpeg;base64,","面对争论，我们应保持理智，先听清楚对方的意见。":"data:audio/mpeg;base64,","哭泣":"data:audio/mpeg;base64,","看到孩子独自坐在角落里哭泣，老师轻轻地走了过去。":"data:audio/mpeg;base64,","否决":"data:audio/mpeg;base64,","经过充分讨论，委员会否决了这项提案。":"data:audio/mpeg;base64,","出息":"data:audio/mpeg;base64,","父母希望孩子将来有出息，也关心他们是否过得快乐。":"data:audio/mpeg;base64,","娃娃":"data:audio/mpeg;base64,","小女孩抱着心爱的布娃娃，安静地坐在沙发上。":"data:audio/mpeg;base64,","潜移默化":"data:audio/mpeg;base64,","家庭氛围会在潜移默化中影响孩子的行为习惯。":"data:audio/mpeg;base64,","鞭策":"data:audio/mpeg;base64,","老师的鼓励一直鞭策着我，让我不敢轻易放弃。":"data:audio/mpeg;base64,","赋予":"data:audio/mpeg;base64,","不同的经历赋予了这件礼物特殊的意义。":"data:audio/mpeg;base64,","扮演":"data:audio/mpeg;base64,","她在这部话剧中扮演一位勇敢而善良的医生。":"data:audio/mpeg;base64,","鄙视":"data:audio/mpeg;base64,","我们不应该因为别人的职业而鄙视他们。":"data:audio/mpeg;base64,","讥笑":"data:audio/mpeg;base64,","面对同学的失误，他没有讥笑，而是主动帮助对方改正。":"data:audio/mpeg;base64,","恶心":"data:audio/mpeg;base64,","车里浓重的汽油味让她感到恶心。":"data:audio/mpeg;base64,","体面":"data:audio/mpeg;base64,","参加正式活动时，穿着整洁体面是对他人的尊重。":"data:audio/mpeg;base64,","含糊":"data:audio/mpeg;base64,","这个问题关系到大家的利益，请不要含糊其辞。":"data:audio/mpeg;base64,","束缚":"data:audio/mpeg;base64,","他希望摆脱旧观念的束缚，尝试一种全新的创作方式。":"data:audio/mpeg;base64,","魔鬼":"data:audio/mpeg;base64,","故事里的魔鬼虽然看起来可怕，却也有温柔的一面。":"data:audio/mpeg;base64,","神仙":"data:audio/mpeg;base64,","传说中的神仙能够腾云驾雾，往来于天地之间。":"data:audio/mpeg;base64,","健全":"data:audio/mpeg;base64,","这家机构建立了健全的管理制度，各项工作都有明确的流程。":"data:audio/mpeg;base64,","塌":"data:audio/mpeg;base64,","这座年久失修的房子在暴雨中塌了。":"data:audio/mpeg;base64,","反之":"data:audio/mpeg;base64,","充分准备通常能提高效率；反之，仓促行动容易出错。":"data:audio/mpeg;base64,","激素":"data:audio/mpeg;base64,","这篇论文讨论了激素研究中的几种常用方法。":"data:audio/mpeg;base64,","转移":"data:audio/mpeg;base64,","救援人员连夜转移物资，确保安置点有足够的生活用品。":"data:audio/mpeg;base64,","喉咙":"data:audio/mpeg;base64,","正式发言之前，他轻轻地清了清喉咙。":"data:audio/mpeg;base64,","鼻涕":"data:audio/mpeg;base64,","孩子流着鼻涕，妈妈递给他一张纸巾。":"data:audio/mpeg;base64,","之际":"data:audio/mpeg;base64,","新年到来之际，学校向全体师生送上了祝福。":"data:audio/mpeg;base64,","修复":"data:audio/mpeg;base64,","专家们花了几个月时间，终于修复了这幅破损的古画。":"data:audio/mpeg;base64,","宣泄":"data:audio/mpeg;base64,","她把心里的烦恼写进日记，借此宣泄积压的情绪。":"data:audio/mpeg;base64,","许可":"data:audio/mpeg;base64,","未经许可，请不要进入这间实验室。":"data:audio/mpeg;base64,","倡导":"data:audio/mpeg;base64,","学校倡导从身边的小事做起，共同营造节约的风气。":"data:audio/mpeg;base64,","情理":"data:audio/mpeg;base64,","他提出的要求合乎情理，大家都表示支持。":"data:audio/mpeg;base64,","忌讳":"data:audio/mpeg;base64,","与不同文化背景的人交往时，应了解对方忌讳的话题。":"data:audio/mpeg;base64,","外界":"data:audio/mpeg;base64,","为了专心完成研究，他暂时减少了与外界的联系。":"data:audio/mpeg;base64,","狭隘":"data:audio/mpeg;base64,","如果总用狭隘的眼光看问题，就很难理解不同的观点。":"data:audio/mpeg;base64,","偏见":"data:audio/mpeg;base64,","只有增加了解，才能逐渐消除彼此的偏见。":"data:audio/mpeg;base64,","阻挠":"data:audio/mpeg;base64,","尽管受到多方面的阻挠，调查工作仍然继续进行。":"data:audio/mpeg;base64,","尊严":"data:audio/mpeg;base64,","无论一个人从事什么工作，他的尊严都应受到尊重。":"data:audio/mpeg;base64,","理睬":"data:audio/mpeg;base64,","他专心看书，没有理睬周围的议论。":"data:audio/mpeg;base64,","淹没":"data:audio/mpeg;base64,","连续的暴雨使河水上涨，淹没了岸边的农田。":"data:audio/mpeg;base64,","须知":"data:audio/mpeg;base64,","我们应珍惜粮食，须知每一粒米都来之不易。":"data:audio/mpeg;base64,","抹杀":"data:audio/mpeg;base64,","不能因为他的一次失误，就抹杀他过去的贡献。":"data:audio/mpeg;base64,","岁月":"data:audio/mpeg;base64,","无论岁月怎样流逝，她始终记得老师的教诲。":"data:audio/mpeg;base64,","沉淀":"data:audio/mpeg;base64,","经过多年的实践，这些经验逐渐沉淀下来，成为团队的宝贵财富。":"data:audio/mpeg;base64,"};
function backup(){const content=JSON.stringify({format:'ntc-hsk6-bai32-v3',profile:student},null,2);let url=URL.createObjectURL(new Blob([content],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='HSK6_Bai32_TienDo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function restore(){let input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{try{let v=JSON.parse(await input.files[0].text()),p=v.profile;if(v.format!=='ntc-hsk6-bai32-v3'||!p||typeof p.name!=='string'||typeof p.clas!=='string'||!Array.isArray(p.studied)||p.studied.some(id=>!Number.isInteger(id)||id<0||id>=52)||!p.memory)throw Error();if(!confirm('恢复第32课学习记录？当前记录将被替换。'))return;let id=store.active||'local';let clean=createStudent(p.name,p.clas);clean.studied=[...new Set(p.studied)];for(let k=0;k<52;k++)if(['remembered','review'].includes(p.memory[k]))clean.memory[k]=p.memory[k];if(p.bookmark&&Number.isInteger(p.bookmark.g)&&p.bookmark.g>=0&&p.bookmark.g<5&&Number.isInteger(p.bookmark.idx)&&p.bookmark.idx>=0&&p.bookmark.idx<group(p.bookmark.g).length)clean.bookmark=p.bookmark;for(let key of ['quizHistory','orderHistory'])if(Array.isArray(p[key]))clean[key]=p[key].filter(r=>r&&Array.isArray(r.answers)&&r.answers.every(a=>Number.isInteger(a.id)&&a.id>=0&&a.id<52&&typeof a.ok==='boolean'));clean.timeMs=Math.max(0,Number(p.timeMs)||0);store.profiles[id]=clean;store.active=id;student=clean;ui={page:5,g:0,idx:0,pinyin:false};save();render();toast('已恢复已学词语、复习状态与练习记录。')}catch(e){toast('无法读取有效的HSK6第32课学习记录。')}});input.click()}
root.addEventListener('click',event=>{let b=event.target.closest('button');if(!b||b.disabled)return;const data=b.dataset;if(data.audioWord!==undefined){speak(WORDS[+data.audioWord].w);return}if(data.audioExample!==undefined){speak(WORDS[+data.audioExample].s);return}if(data.page!==undefined){go(+data.page);return}if(data.group!==undefined){chooseGroup(+data.group);return}if(data.word!==undefined){let id=+data.word;ui.g=groupOf(id);ui.idx=id-ui.g*10;go(1);return}if(data.answer!==undefined){stopAudio();pickQuiz(+data.answer);return}if(data.chunk!==undefined){addChunk(+data.chunk);return}if(data.remove!==undefined){removeChunk(+data.remove);return}let a=data.action;if(!a)return;if(a==='stop'){stopAudio();return}switch(a){case'strokes':animateWriting();return;case'resume':ui.g=student.bookmark.g;ui.idx=student.bookmark.idx;go(1);return;case'pinyin':ui.pinyin=!ui.pinyin;break;case'prev-study':{let id=currentWord().id-1;ui.g=groupOf(id);ui.idx=id-ui.g*10;break}case'mark-study':stopAudio();markStudy();return;case'flip':student.flash.flipped=!student.flash.flipped;break;case'flash-all':if(!allLearned()){go(2);return}ui.page=2;startFlash('all');return;case'flash-weak':if(!allLearned()){go(2);return}ui.page=2;startFlash('weak');return;case'flash-prev':student.flash.at--;student.flash.flipped=false;break;case'flash-next':student.flash.at++;student.flash.flipped=false;break;case'quiz-page':go(3);return;case'order-page':go(4);return;case'stats-page':go(5);return;case'quiz-as-meaning':student.quiz.questions[student.quiz.at].type='meaning';break;case'quiz-next':stopAudio();nextQuiz();return;case'quiz-restart':startQuiz();return;case'quiz-retry':startQuiz(true,student.quiz.questions.filter(x=>x.picked!==x.correct).map(x=>x.id));return;case'order-undo':removeChunk(student.order.selected.length-1);return;case'order-clear':student.order.selected=[];break;case'order-check':checkOrder();return;case'order-next':stopAudio();nextOrder();return;case'order-restart':startOrder();return;case'order-retry':startOrder(student.order.answers.filter(x=>!x.ok).map(x=>x.id));return;case'backup':backup();return;case'restore':restore();return;default:return}save();render()});
root.addEventListener('change',event=>{if(event.target.id==='ntc-rate')speed=Number(event.target.value)});


let strokeWriters=[],strokeRun=0;
async function animateWriting(){const token=++strokeRun,list=[...strokeWriters];if(!list.length){toast('暂时无法显示笔顺。');return;}const button=root.querySelector('[data-action="strokes"]');if(button)button.disabled=true;try{for(const w of list)await w.hideCharacter({duration:0});for(const w of list){if(token!==strokeRun)return;await w.animateCharacter();}}finally{if(token===strokeRun&&button)button.disabled=false;}}

let lastTick=Date.now();setInterval(()=>{let now=Date.now();if(student&&!document.hidden){student.timeMs+=Math.min(now-lastTick,15000);save()}lastTick=now},15000);
window.addEventListener('pagehide',()=>{save();stopAudio()});
if(student&&ui.page>=2&&ui.page<=4&&allLearned()){if(ui.page===2&&!student.flash)startFlash('all',false);if(ui.page===3&&!student.quiz)startQuiz(false);if(ui.page===4&&!student.order)startOrder(null,false)}
save();render();if(!storageOK)toast('浏览器阻止保存数据，建议导出学习记录作为备份。');

